import os, json, re

BANNED_WORDS = [
    "plugd",
    "ai businesses",
    "research & editorial",
    "official master class",
    "sovereign",
    "sovereignty",
    "asymmetric",
    "monastic",
    "forensic",
    "as an ai",
    "lorem ipsum"
]

def make_clean_file(dest_path, title, paras):
    for idx, p in enumerate(paras):
        if "\n" in p or "\r" in p:
            raise ValueError(f"Linebreak in para {idx+1}")
        w = len(p.split())
        if w < 35 or w > 230:
            raise ValueError(f"Para {idx+1} word count {w} outside 35-230: {p[:30]}...")
        p_lower = p.lower()
        for bw in BANNED_WORDS:
            if bw in p_lower:
                raise ValueError(f"Banned word '{bw}' in para {idx+1}")
    total_w = len(title.split()) + sum(len(p.split()) for p in paras)
    content = f"# {title}\n\n" + "\n\n".join(paras) + "\n"
    os.makedirs(os.path.dirname(dest_path), exist_ok=True)
    with open(dest_path, "w", encoding="utf-8") as f:
        f.write(content)
    print(f"Created {os.path.basename(dest_path)}: {len(paras)} paras, {total_w} words.")
    return total_w

